from pysat.solvers import Glucose4
from pysat.card import CardEnc
import itertools

n = 19
edges = []
edge_vars = {}
var_counter = 1

for i in range(n):
    for j in range(i + 1, n):
        edges.append((i, j))
        edge_vars[(i, j)] = var_counter
        edge_vars[(j, i)] = var_counter
        var_counter += 1

solver = Glucose4()

# Girth >= 7
# No C3
for c in itertools.combinations(range(n), 3):
    for p in [[c[0], c[1], c[2]]]:
        solver.add_clause([-edge_vars[(p[0], p[1])], -edge_vars[(p[1], p[2])], -edge_vars[(p[0], p[2])]])

# No C4
for c in itertools.combinations(range(n), 4):
    for p in itertools.permutations(c):
        if p[0] < p[1] and p[0] < p[3] and p[1] < p[3]:
            solver.add_clause([-edge_vars[(p[0], p[1])], -edge_vars[(p[1], p[2])], -edge_vars[(p[2], p[3])], -edge_vars[(p[3], p[0])]])

# No C5
for c in itertools.combinations(range(n), 5):
    for p in itertools.permutations(c):
        if p[0] == min(p) and p[1] < p[4]:
            solver.add_clause([-edge_vars[(p[0], p[1])], -edge_vars[(p[1], p[2])], -edge_vars[(p[2], p[3])], -edge_vars[(p[3], p[4])], -edge_vars[(p[4], p[0])]])

# No C6
for c in itertools.combinations(range(n), 6):
    for p in itertools.permutations(c):
        if p[0] == min(p) and p[1] < p[5]:
            solver.add_clause([-edge_vars[(p[0], p[1])], -edge_vars[(p[1], p[2])], -edge_vars[(p[2], p[3])], -edge_vars[(p[3], p[4])], -edge_vars[(p[4], p[5])], -edge_vars[(p[5], p[0])]])

print("Clauses added for girth")

# 3-colorable
color_vars = {}
for i in range(n):
    for c in range(3):
        color_vars[(i, c)] = var_counter
        var_counter += 1

for i in range(n):
    solver.add_clause([color_vars[(i, 0)], color_vars[(i, 1)], color_vars[(i, 2)]])
    solver.add_clause([-color_vars[(i, 0)], -color_vars[(i, 1)]])
    solver.add_clause([-color_vars[(i, 1)], -color_vars[(i, 2)]])
    solver.add_clause([-color_vars[(i, 0)], -color_vars[(i, 2)]])

for i in range(n):
    for j in range(i + 1, n):
        for c in range(3):
            solver.add_clause([-edge_vars[(i, j)], -color_vars[(i, c)], -color_vars[(j, c)]])

print("Clauses added for coloring")

# Edges >= 32
edge_var_list = [edge_vars[e] for e in edges]
cnf = CardEnc.atleast(lits=edge_var_list, bound=32, top_id=var_counter - 1, encoding=1)
for clause in cnf.clauses:
    solver.add_clause(clause)

print("Solving...")
if solver.solve():
    print("SAT")
    model = solver.get_model()
    res_edges = [e for e in edges if model[edge_vars[e] - 1] > 0]
    print(res_edges)
else:
    print("UNSAT")

